import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import Sidebar from '../components/layout/Sidebar';
import { getCompanyRoadmap, getProfile } from '../services/api';
import api from '../services/api';

const COMPANIES = ['Zoho','TCS','Infosys','Wipro','Accenture','Amazon','Google','Microsoft','Freshworks','Cognizant'];

export default function CompanyQuestions() {
  const navigate = useNavigate();
  const [selectedCompany, setSelectedCompany] = useState('');
  const [roadmap, setRoadmap] = useState(null);
  const [loading, setLoading] = useState(false);
  const [activeTab, setActiveTab] = useState('All');

  // Practice mode states
  const [practiceMode, setPracticeMode] = useState(false);
  const [practiceQuestions, setPracticeQuestions] = useState([]);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [showAnswer, setShowAnswer] = useState(false);
  const [score, setScore] = useState(0);
  const [answered, setAnswered] = useState([]);
  const [finished, setFinished] = useState(false);

  useEffect(() => {
    getProfile()
      .then(res => { if (res.data?.dreamCompany) setSelectedCompany(res.data.dreamCompany); })
      .catch(() => {});
  }, []);

  useEffect(() => {
    if (selectedCompany) {
      setLoading(true);
      getCompanyRoadmap(selectedCompany)
        .then(res => { setRoadmap(res.data); setActiveTab('All'); })
        .catch(() => {})
        .finally(() => setLoading(false));
    }
  }, [selectedCompany]);

  const getFilteredQuestions = () => {
    if (!roadmap) return [];
    if (activeTab === 'All') return Object.values(roadmap.questionsByType || {}).flat();
    return roadmap.questionsByType?.[activeTab] || [];
  };

  const startPractice = () => {
    const qs = getFilteredQuestions();
    if (qs.length === 0) { alert('No questions available!'); return; }
    setPracticeQuestions(qs);
    setCurrentIndex(0);
    setShowAnswer(false);
    setScore(0);
    setAnswered([]);
    setFinished(false);
    setPracticeMode(true);
  };

  const handleAnswer = (knew) => {
    const newAnswered = [...answered, { index: currentIndex, knew }];
    setAnswered(newAnswered);
    if (knew) setScore(s => s + 1);

    if (currentIndex < practiceQuestions.length - 1) {
      setCurrentIndex(i => i + 1);
      setShowAnswer(false);
    } else {
      setFinished(true);
    }
  };

  const types = roadmap ? ['All', ...Object.keys(roadmap.questionsByType || {})] : ['All'];

  // Practice finished screen
  if (practiceMode && finished) {
    const total = practiceQuestions.length;
    const pct = Math.round((score / total) * 100);
    return (
      <div className="app-layout">
        <Sidebar />
        <div className="main-content fade-in">
          <div style={{ textAlign: 'center', padding: '3rem' }}>
            <div style={{ fontSize: '4rem', marginBottom: '1rem' }}>
              {pct >= 70 ? '🎉' : pct >= 40 ? '💪' : '📚'}
            </div>
            <h1 style={{ fontSize: '2rem', fontWeight: 800, marginBottom: '0.5rem' }}>
              Practice Complete!
            </h1>
            <p style={{ fontSize: '1.2rem', color: 'var(--mid)', marginBottom: '2rem' }}>
              {selectedCompany} — {activeTab} Questions
            </p>

            <div style={{
              display: 'inline-block', background: 'var(--card)',
              borderRadius: '16px', padding: '2rem 3rem',
              boxShadow: 'var(--shadow)', marginBottom: '2rem'
            }}>
              <p style={{ fontSize: '3rem', fontWeight: 800, color: pct >= 70 ? '#00b894' : pct >= 40 ? '#f77f00' : '#ff4444' }}>
                {score}/{total}
              </p>
              <p style={{ fontSize: '1.2rem', color: 'var(--mid)' }}>
                {pct}% Accuracy
              </p>
            </div>

            <div style={{ marginBottom: '2rem' }}>
              <p style={{ fontSize: '1rem', color: pct >= 70 ? '#00b894' : '#f77f00', fontWeight: 600 }}>
                {pct >= 70 ? '✅ Great job! You are well prepared for ' + selectedCompany + '!' :
                 pct >= 40 ? '⚠️ Good effort! Practice more to improve.' :
                 '📚 Keep studying! Review the hints and try again.'}
              </p>
            </div>

            <div style={{ display: 'flex', gap: '1rem', justifyContent: 'center' }}>
              <button onClick={() => startPractice()}
                style={{
                  background: '#6c63ff', color: 'white', border: 'none',
                  borderRadius: '8px', padding: '0.8rem 2rem',
                  cursor: 'pointer', fontWeight: 700
                }}>
                🔄 Practice Again
              </button>
              <button onClick={() => { setPracticeMode(false); setFinished(false); }}
                style={{
                  background: 'var(--card)', color: 'var(--text)',
                  border: '2px solid var(--border)', borderRadius: '8px',
                  padding: '0.8rem 2rem', cursor: 'pointer', fontWeight: 700
                }}>
                ← Back to Questions
              </button>
            </div>
          </div>
        </div>
      </div>
    );
  }

  // Practice mode — Question card
  if (practiceMode) {
    const q = practiceQuestions[currentIndex];
    return (
      <div className="app-layout">
        <Sidebar />
        <div className="main-content fade-in">
          <div style={{ maxWidth: '700px', margin: '0 auto' }}>

            {/* Header */}
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1.5rem' }}>
              <button className="back-btn" onClick={() => setPracticeMode(false)}>
                ← Exit Practice
              </button>
              <div style={{ textAlign: 'right' }}>
                <p style={{ fontWeight: 700, color: '#6c63ff' }}>
                  {currentIndex + 1} / {practiceQuestions.length}
                </p>
                <p style={{ fontSize: '0.8rem', color: 'var(--mid)' }}>
                  Score: {score} ✅
                </p>
              </div>
            </div>

            {/* Progress Bar */}
            <div style={{ height: '6px', background: '#e2e8f0', borderRadius: '999px', marginBottom: '1.5rem' }}>
              <div style={{
                height: '100%',
                width: `${((currentIndex + 1) / practiceQuestions.length) * 100}%`,
                background: '#6c63ff', borderRadius: '999px',
                transition: 'width 0.3s ease'
              }} />
            </div>

            {/* Question Card */}
            <div style={{
              background: 'var(--card)', borderRadius: '16px',
              padding: '2rem', boxShadow: 'var(--shadow)', marginBottom: '1.5rem'
            }}>
              <div style={{ display: 'flex', gap: '0.5rem', marginBottom: '1rem' }}>
                <span style={{
                  background: '#6c63ff20', color: '#6c63ff',
                  padding: '0.2rem 0.7rem', borderRadius: '20px',
                  fontSize: '0.75rem', fontWeight: 700
                }}>
                  {q.questionType}
                </span>
                <span style={{
                  background: '#f0f0f0', color: '#666',
                  padding: '0.2rem 0.7rem', borderRadius: '20px',
                  fontSize: '0.75rem', fontWeight: 600
                }}>
                  {q.difficulty || 'Medium'}
                </span>
                {q.yearAsked && (
                  <span style={{
                    background: '#fff3e0', color: '#f77f00',
                    padding: '0.2rem 0.7rem', borderRadius: '20px',
                    fontSize: '0.75rem', fontWeight: 600
                  }}>
                    {q.yearAsked}
                  </span>
                )}
              </div>

              <h2 style={{ fontSize: '1.2rem', fontWeight: 700, lineHeight: 1.6, marginBottom: '1.5rem' }}>
                Q{currentIndex + 1}. {q.questionText}
              </h2>

              {/* Show Answer Button */}
              {!showAnswer ? (
                <button onClick={() => setShowAnswer(true)}
                  style={{
                    background: '#6c63ff', color: 'white', border: 'none',
                    borderRadius: '8px', padding: '0.7rem 1.5rem',
                    cursor: 'pointer', fontWeight: 700, width: '100%'
                  }}>
                  💡 Show Answer / Hint
                </button>
              ) : (
                <div style={{
                  background: '#e6fff9', border: '1px solid #00b894',
                  borderRadius: '10px', padding: '1rem', marginBottom: '1rem'
                }}>
                  <p style={{ fontWeight: 700, color: '#00b894', marginBottom: '0.5rem' }}>
                    💡 Answer / Hint:
                  </p>
                  <p style={{ fontSize: '0.95rem', lineHeight: 1.6 }}>
                    {q.answerHint || 'No hint available'}
                  </p>
                </div>
              )}
            </div>

            {/* Did you know this? */}
            {showAnswer && (
              <div style={{
                background: 'var(--card)', borderRadius: '12px',
                padding: '1.5rem', boxShadow: 'var(--shadow)',
                textAlign: 'center'
              }}>
                <p style={{ fontWeight: 700, fontSize: '1rem', marginBottom: '1rem' }}>
                  Did you know this answer?
                </p>
                <div style={{ display: 'flex', gap: '1rem', justifyContent: 'center' }}>
                  <button onClick={() => handleAnswer(true)}
                    style={{
                      background: '#00b894', color: 'white', border: 'none',
                      borderRadius: '8px', padding: '0.7rem 2rem',
                      cursor: 'pointer', fontWeight: 700, fontSize: '1rem'
                    }}>
                    ✅ Yes, I knew it!
                  </button>
                  <button onClick={() => handleAnswer(false)}
                    style={{
                      background: '#ff4444', color: 'white', border: 'none',
                      borderRadius: '8px', padding: '0.7rem 2rem',
                      cursor: 'pointer', fontWeight: 700, fontSize: '1rem'
                    }}>
                    ❌ Need more practice
                  </button>
                </div>
              </div>
            )}
          </div>
        </div>
      </div>
    );
  }

  // Main page
  return (
    <div className="app-layout">
      <Sidebar />
      <div className="main-content fade-in">
        <div className="page-header">
          <button className="back-btn" onClick={() => navigate('/dashboard')}>← Back</button>
          <div>
            <h1>🏢 Previous Year Questions</h1>
            <p style={{ color: 'var(--mid)', fontSize: '0.9rem' }}>
              Company-specific question banks and practice
            </p>
          </div>
        </div>

        {/* Company Selector */}
        <div className="card" style={{ marginBottom: '1.5rem' }}>
          <h3 style={{ fontWeight: 700, marginBottom: '1rem' }}>Select Company</h3>
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: '0.6rem' }}>
            {COMPANIES.map(c => (
              <button key={c}
                style={{
                  padding: '0.5rem 1rem', borderRadius: '50px',
                  border: selectedCompany === c ? 'none' : '1px solid var(--border)',
                  background: selectedCompany === c ? 'var(--primary)' : 'white',
                  color: selectedCompany === c ? 'white' : 'var(--dark)',
                  fontWeight: 600, fontSize: '0.88rem',
                  cursor: 'pointer', transition: 'all 0.2s'
                }}
                onClick={() => setSelectedCompany(c)}>
                {c}
              </button>
            ))}
          </div>
        </div>

        {loading && <div className="loading-wrap"><div className="spinner"></div></div>}

        {roadmap && !loading && (
          <>
            {/* Roadmap */}
            <div className="card" style={{ marginBottom: '1.5rem' }}>
              <div className="card-header">
                <span className="card-title">🗺️ {selectedCompany} Interview Roadmap</span>
                <span style={{ fontSize: '0.85rem', color: 'var(--mid)' }}>
                  {roadmap.totalQuestions} questions available
                </span>
              </div>
              {roadmap.stages?.map(stage => (
                <div className="roadmap-stage" key={stage.stage}>
                  <div className="stage-num">{stage.stage}</div>
                  <div>
                    <div style={{ fontWeight: 700, marginBottom: '0.25rem' }}>{stage.title}</div>
                    <div style={{ fontSize: '0.88rem', color: 'var(--mid)' }}>{stage.description}</div>
                  </div>
                </div>
              ))}
            </div>

            {/* Questions + Practice */}
            <div className="card">
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1rem' }}>
                <span className="card-title">❓ Interview Questions</span>
                <button onClick={startPractice}
                  style={{
                    background: '#6c63ff', color: 'white', border: 'none',
                    borderRadius: '8px', padding: '0.6rem 1.5rem',
                    cursor: 'pointer', fontWeight: 700, fontSize: '0.9rem'
                  }}>
                  🚀 Start Practice
                </button>
              </div>

              {/* Tabs */}
              <div className="tabs" style={{ borderBottom: 'none', marginBottom: '1rem' }}>
                {types.map(t => (
                  <button key={t}
                    className={`tab ${activeTab === t ? 'active' : ''}`}
                    onClick={() => setActiveTab(t)}>
                    {t}
                  </button>
                ))}
              </div>

              {/* Questions List */}
              {getFilteredQuestions().map((q, idx) => (
                <div className="company-q-card" key={q.id || idx}>
                  <span className={`type-badge type-${q.questionType}`}>{q.questionType}</span>
                  <h4>{q.questionText}</h4>
                  {q.answerHint && <div className="hint">💡 Hint: {q.answerHint}</div>}
                  {q.yearAsked && (
                    <div style={{ fontSize: '0.78rem', color: 'var(--mid)', marginTop: '0.4rem' }}>
                      Asked in: {q.yearAsked}
                    </div>
                  )}
                </div>
              ))}

              {getFilteredQuestions().length === 0 && (
                <div className="empty-state">
                  <div className="e-icon">📭</div>
                  <h3>No questions found</h3>
                </div>
              )}
            </div>
          </>
        )}

        {!selectedCompany && !loading && (
          <div className="empty-state">
            <div className="e-icon">🏢</div>
            <h3>Select a company to begin</h3>
          </div>
        )}
      </div>
    </div>
  );
}
